comms.text:
@1 וּמַלִיל יְיָ עִם מֹשֶׁה בְּטּוּרָא דְסִינַי לְמֵימָר:
@2 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעַלוּן לְאַרְעָא דִי אֲנָא יָהֵב לְכוֹן וְתַשְּׁמֵט אַרְעָא שְׁמִטְתָא קֳדָם יְיָ:
@3 שִׁית שְׁנִין תִּזְרַע חַקְלָךְ וְשִׁית שְׁנִין תִכְסַח כַּרְמָךְ וְתִכְנוֹשׁ יָת עֲלַלְתָּהּ:
@4 וּבְשַׁתָּא שְׁבִיעֲתָא נְיַח שְׁמִטְתָא יְהֵי לְאַרְעָא דְתַשְׁמֵט קֳדָם יְיָ חַקְלָךְ לָא תִזְרַע וְכַרְמָךְ לָא תִכְסָח:
@5 יָת כַּתֵּי דַחֲצָדָךְ לָא תֶחֱצַד וְיָת עִנְבֵי שִׁבְקָךְ לָא תִקְטוֹף שְׁנַת שְׁמִטְתָא יְהֵי לְאַרְעָא:
@6 וּתְהֵי שְׁמִטַת אַרְעָא לְכוֹן לְמֵיכַל לָךְ וּלְעַבְדָךְ וּלְאַמְתָךְ וְלַאֲגִירָךְ וּלְתוֹתָבָךְ דְדָיְרִין עִמָךְ:
@7 וְלִבְעִירָךְ וּלְחַיְתָא דִי בְאַרְעָךְ תְּהֵי כָל עֲלַלְתַּהּ לְמֵיכָל:
@8 וְתִמְנֵי לָךְ שְׁבַע שְׁמִיטִין דִשְׁנִין שְׁבַע שְׁנִין שְׁבַע זִמְנִין וִיהוֹן לָךְ יוֹמֵי שְּׁבַע שְׁמִטִין דִשְׁנִין אַרְבְּעִין וְתֵשַׁע שְׁנִין:
@9 וְתַעֲבַר שׁוֹפָר יַבָּבָא בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא בְּיוֹמָא דְכִפּוּרַיָא תַּעַבְרוּן שׁוֹפָרָא בְּכָל אַרְעֲכוֹן:
@10 וּתְקַדְשׁוּן יָת שְׁנַת חַמְשִׁין שְׁנִין וְתַקְרוּן חֵרוּתָא בְּאַרְעָא לְכָל יָתְבָהָא יוֹבֵלָא הִיא תְּהֵי לְכוֹן וּתְתוּבוּן גְבַר לְאַחֲסַנְתֵּהּ וּגְבַר לְזַרְעִיתֵהּ תְּתוּבוּן:
@11 יוֹבֵלָא הִיא שְׁנַת חַמְשִׁין שְׁנִין תְּהֵי לְכוֹן לָא תִזְרְעוּן וְלָא תַחְצְדוּן יַת כַּתָּהָא וְלָא תִקְטְפוּן יַת שִׁבְקָהָא:
@12 אֲרֵי יוֹבֵלָא הִיא קוּדְשָׁא תְּהֵי לְכוֹן מִן חַקְלָא תֵּיכְלוּן יָת עֲלַלְתָּהּ:
@13 בְּשַׁתָּא דְיוֹבֵלָא הָדָא תְּתוּבוּן גְבַר לְאַחֲסַנְתֵּהּ:
@14 וַאֲרֵי תְזַבֵּן זְבִינִין לְחַבְרָךְ אוֹ תִזְבֵּן מִידָא דְחַבְרָךְ לָא תוֹנוּן גְבַר יָת אֲחוֹהִי:
@15 בְּמִנְיַן שְׁנַיָא בָּתַר יוֹבֵלָא תִּזְבֵּן מִן חַבְרָךְ בְּמִנְיַן שְׁנֵי עֲלַלְתָּא יְזַבֶּן לָךְ:
@16 לְפוּם סְגִיאוּת שְׁנַיָא תַּסְגֵי זְבִינוֹהִי וּלְפוּם זְעֵרוּת שְׁנַיָא תַּזְעֵר זְבִינוֹהִי אֲרֵי מִנְיַן עֲלַלְתָּא הוּא מְזַבֵּן לָךְ:
@17 וְלָא תוֹנוּן גְבַר יָת חַבְרֵהּ וְתִדְחַל מֵאֱלָהָךְ אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@18 וְתַעְבְּדוּן יָת קְיָמַי וְיָת דִינַי תִּטְּרוּן וְתַעֲבְּדוּן יָתְהוֹן וְתֵיתְבוּן עַל אַרְעָא לְרָחֲצָן:
@19 וְתִתֵּן אַרְעָא אִבַּהּ וְתֵיכְלוּן לְמִשְׂבָּע וְתֵיתְבוּן לְרָחֲצָן עֲלַהּ:
@20 וַאֲרֵי תֵימְרוּן מָא נֵיכוּל בְּשַׁתָּא שְׁבִיעֵתָא הָא לָא נִזְרָע וְלָא נִכְנוֹשׁ יָת עֲלַלְתָּנָא:
@21 וֶאֱפַקֵד יָת בִּרְכְּתִי לְכוֹן בְּשַׁתָּא שְׁתִיתֵתָא וְתַעְבֵּד יָת עֲלַלְתָּא לִתְלַת שְׁנִין:
@22 וְתִזְרְעוּן יָת שַׁתָּא תְמִינֵתָא וְתֵיכְלוּן מִן עֲלַלְתָּא עַתִּיקָא עַד שַׁתָּא תְשִׁיעֵתָא עַד מֵעַל עֲלַלְתַּהּ תֵּיכְלוּן עַתִּיקָא:
@23 וְאַרְעָא לָא תִזְדַבַּן לַחֲלוּטִין אֲרֵי דִילִי אַרְעָא אֲרֵי דַיָרִין וְתוֹתָבִין אַתּוּן קֳדָמַי:
@24 וּבְכֹל אַרְעָא אַחֲסַנְתְּכוֹן פֻּרְקָנָא תִּתְּנוּן לְאַרְעָא:
@25 אֲרֵי יִתְמַסְכַּן אָחוּךְ וִיזַבֵּן מֵאַחֲסַנְתֵּהּ וְיֵיתֵי פָרִיקֵהּ דְקָרִיב לֵהּ וְיִפְרוֹק יָת זְבִינֵי אֲחוּהִי:
@26 וּגְבַר אֲרֵי לָא יְהֵי לֵהּ פָּרִיק וְתַדְבֵּק יְדֵהּ וְיַשְׁכַּח כְּמִסַת פֻּרְקָנֵהּ:
@27 וִיחַשֵׁב יָת שְׁנֵי זְבִינוֹהִי וְיָתֵב יָת מוֹתָרָא לִגְבַר דִי זַבֶּן לֵהּ וִיתוּב לְאַחֲסַנְתֵּהּ:
@28 וְאִם לָא תַשְׁכַּח יְדֵהּ כְּמִסַת אֲתֵב לֵהּ וִיהֵי זְבִינוֹהִי בִּידָא דִזְבַן יָתֵהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִפּוֹק בְּיוֹבֵלָא וִיתוּב לְאַחֲסַנְתֵּהּ:
@29 וּגְבַר אֲרֵי יְזַבֵּן בֵּית מוֹתַב קַרְתָּא מַקְפָא שׁוּר וּתְהֵי פוּרְקָנֵהּ עַד מִשְׁלַם שַׁתָּא דִזְבִינוֹהִי עִדָן בְּעִדָן תְּהֵי פוּרְקָנֵהּ:
@30 וְאִם לָא יִתְפָּרַק עַד מִשְׁלַם לֵהּ שַׁתָּא שְׁלֶמְתָּא וִיקוּם בֵּיתָא דִי בְקַרְתָּא דִי לֵהּ שׁוּרָא לַחֲלוּטִין לְדִי זְבַן יָתֵהּ לְדָרוֹהִי לָא יִפּוֹק בְּיוֹבֵלָא:
@31 וּבָתֵּי פַצְחַיָא דִי לֵית לְהוֹן שׁוּר מַקַף סְחוֹר סְחוֹר עַל חֲקַל אַרְעָא יִתְחַשָׁב פֻּרְקָנָא תְּהֵי לֵהּ וּבְיוֹבֵלָא יִפּוֹק:
@32 וְקִרְוֵי לֵיוָאֵי בָּתֵּי קִרְוֵי אַחֲסַנְתְּהוֹן פּוּרְקַן עָלָם תְּהֵי לְלֵיוָאֵי:
@33 וְדִי יִפְרוֹק מִן לֵיוָאֵי וְיִפּוֹק זְבִין בֵּיתָא וְקַרְתָּא אַחֲסַנְתֵּהּ בְּיוֹבֵלָא אֲרֵי בָתֵּי קִרְוֵי לֵיוָאֵי הִיא אַחְסַנְתְּהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@34 וַחֲקַל רְוַח קִרְוֵיהוֹן לָא יִזְדַבָּן אֲרֵי אַחֲסָנַת עָלָם הוּא לְהוֹן:
@35 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ וּתְמוּט יְדֵהּ עִמָךְ וְתַתְקַף בֵּהּ דַיַר וְתוֹתָב וִיחֵי עִמָךְ:
@36 לָא תִסַב מִנֵהּ חִבּוּלְיָא וְרִבִּיתָא וְתִדְחַל מֵאֱלָהָךְ וִיחֵי אָחוּךְ עִמָךְ:
@37 יָת כַּסְפָּךְ לָא תִתֵּן לֵהּ בְּחִבּוּלְיָא וּבְרִבִּיתָא לָא תִתֵּן מֵיכְלָךְ:
@38 אֲנָא יְיָ אֱלָהֲכוֹן דִי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם לְמִתַּן לְכוֹן יָת אַרְעָא דִכְנַעַן לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ:
@39 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ עִמָךְ וְיִזְדַבַּן לָךְ לָא תִפְלַח בֵּהּ פָּלְחַן עַבְדִין:
@40 כַּאֲגִירָא כְתוֹתָבָא יְהֵי עִמָךְ עַד שַׁתָּא דְיוֹבֵלָא יִפְלַח עִמָךְ:
@41 וְיִפּוֹק מֵעִמָךְ הוּא וּבְנוֹהִי עִמֵהּ וִיתוּב לְזַרְעִיתֵהּ וּלְאַחֲסָנַת אֲבָהָתוֹהִי יְתוּב:
@42 אֲרֵי עַבְדַי אִנוּן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם לָא יִזְדַבְּנוּן זְבוּן עַבְדִין:
@43 לָא תִפְלָח בֵּהּ בְּקַשְׁיוּ וְתִדְחַל מֵאֱלָהָךְ:
@44 וְעַבְדָךְ וְאַמְתָךְ דִי יְהוֹן לָךְ מִן עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן מִנְהוֹן תִּקְנוּן עַבְדִין וְאַמְהָן:
@45 וְאַף מִבְּנֵי תוֹתָבַיָא עָרְלַיָא דְדָיְרִין עִמְכוֹן מִנְהוֹן תִּקְנוּן וּמִזַרְעִיתְהוֹן דְעִמְכוֹן דִי אִתְיְלִידוּ בְּאַרְעֲכוֹן וִיהוֹן לְכוֹן לְאַחֲסָנָא:
@46 וְתַחֲסוּן יָתְהוֹן לִבְנֵיכוֹן בַּתְרֵיכוֹן לִירוּתַת אַחֲסָנָא לְעָלָם בְּהוֹן תִּפְלְחוּן וּבְאֲחֵיכוֹן בְּנֵי יִשְׂרָאֵל גְבַר בַּאֲחוּהִי לָא תִפְלַח בֵּהּ בְּקַשְׁיוּ:
@47 וַאֲרֵי תַדְבֵּק יַד עָרֵל וְתוֹתָב עִמָךְ וְיִתְמַסְכַּן אָחוּךְ עִמֵהּ וְיִזְדַבַּן לְעָרֵל תּוֹתָב עִמָךְ אוֹ לְאַרְמַי זַרְעִית גִיוֹרָא:
@48 בָּתַר דְיִזְדַבַּן פֻּרְקָנָא תְּהֵי לֵהּ חַד מֵאֲחוֹהִי יִפְרְקִנֵהּ:
@49 אוֹ אַח אֲבוּהִּי אוֹ בַר אַח אֲבוּהִי יִפְרְקִנֵהּ אוֹ מִקָרִיב בִּשְׂרֵהּ מִזַרְעִיתֵהּ יִפְרְקִנֵהּ אוֹ דְתַדְבֵּק יְדֵהּ וְיִתְפָּרָק:
@50 וִיחַשֵׁב עִם זָבְנֵהּ מִשַׁתָּא דְאִזְדַבַּן לֵהּ עַד שַׁתָּא דְיוֹבֵלָא וִיהֵי כְּסַף זְבִינוֹהִי בְּמִנְיַן שְׁנַיָא כְּיוֹמֵי אֲגִירָא יְהֵי עִמֵהּ:
@51 אִם עוֹד סְגִיוּת בִּשְׁנַיָא לְפוּמְהֵן יָתֵב פֻּרְקָנֵהּ מִכְּסַף זְבִינוֹהִי:
@52 וְאִם זְעֵר יִשְׁתָּאַר בִּשְׁנַיָא עַד שַׁתָּא דְיוֹבֵלָא וִיחַשֶׁב לֵהּ כְּפוּם שְׁנוֹהִי יָתֵב יָת פּוּרְקָנֵהּ:
@53 כַּאֲגִיר שְׁנָא בִּשְׁנָא יְהֵי עִמֵהּ לָא יִפְלַח בֵּהּ בְּקַשְׁיוּ לְעֵינָיךְ:
@54 וְאִם לָא יִתְפָּרַק בְּאִלֵין וְיִפּוֹק בְּשַׁתָּא דְיוֹבֵלָא הוּא וּבְנוֹהִי עִמֵהּ:
@55 אֲרֵי דִילִי בְנֵי יִשְׂרָאֵל עַבְדִין עַבְדַי אִנוּן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהֲכוֹן:
@56 לָא תַעְבְּדוּן לְכוֹן טַעֲוָן וְצֶלֶם וְקָמָא לָא תְקִימוּן לְכוֹן וְאֶבֶן סָגְדָא לָא תִתְּנוּן בְּאַרְעֲכוֹן לְמִסְגֻד עֲלַהּ אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@57 יָת יוֹמֵי שַׁבַּיָא דִילִי תִטְרוּן וּלְבֵית מַקְדְשִׁי תְּהוֹן דָחֲלִין אֲנָא יְיָ: פפפ:

@1 **בהר סיני.** מה ענין שמטה אצל הר סיני, והלא כל המצות נאמרו מסיני, אלא מה שמטה נאמרו כללותיה ופרטותיה ודקדוקיה מסיני, אף כלן נאמרו כללותיהן ודקדוקיהן מסיני, כך שנויה בתורת כהנים. ונראה לי שכך פרושה לפי שלא מצינו שמטת קרקעות שנשנית בערבות מואב במשנה תורה, למדנו שכללותיה ופרטותיה כלן נאמרו מסיני, ובא הכתוב ולמד כאן על כל דבור שנדבר למשה שמסיני היו כלם כללותיהן ודקדוקיהן, וחזרו ונשנו בערבות מואב:
@2 **שבת לה'.** לשם ה', כשם שנאמר בשבת בראשית:
@4 **יהיה לארץ.** לשדות ולכרמים: **לא תזמר.** שקוצצין זמורותיה. ותרגומו לא תכסח, ודומה לו (ישעיה לג יב) קוצים כסוחים, (תהלים פ יז) שרפה באש כסוחה:
@5 **את ספיח קצירך.** אפלו לא זרעתה והיא צמחה מן הזרע שנפל בה בעת הקציר, הוא קרוי ספיח: **לא תקצור.** להיות מחזיק בו כשאר קציר, אלא הפקר יהיה לכל: **נזירך.** שהנזרת והפרשת בני אדם מהם ולא הפקרתם: **לא תבצר.** אותם אינך בוצר, אלא מן המפקר:
@6 **והיתה שבת הארץ** וגו' **.** אף על פי שאסרתים עליך, לא באכילה ולא בהנאה אסרתים, אלא שלא תנהוג בהם כבעל הבית, אלא הכל יהיו שוים בה, אתה ושכירך ותושבך: **שבת הארץ לכם לאכלה.** מן השבות אתה אוכל, ואי אתה אוכל מן השמור: **לך ולעבדך ולאמתך.** לפי שנאמר (שמות כג יא) ואכלו אביוני עמך, יכול יהיו אסורים באכילה לעשירים, תלמוד לומר לך ולעבדך ולאמתך, הרי בעלים ועבדים ושפחות אמורים כאן: **ולשכירך ולתושבך.** אף הגוים:
@7 **ולבהמתך ולחיה.** אם חיה אוכלת בהמה לא כל שכן, שמזונותיה עליך, מה תלמוד לומר ולבהמתך, מקיש בהמה לחיה, כל זמן שחיה אוכלת מן השדה האכל לבהמתך מן הבית, כלה לחיה מן השדה כלה לבהמתך מן הבית:
@8 **שבתת שנים.** שמטות שנים. יכול יעשה שבע שנים רצופות שמטה ויעשה יובל אחריהם, תלמוד לומר שבע שנים שבע פעמים, הוי אומר כל שמטה ושמטה בזמנה: **והיו לך ימי שבע** וגו' **.** מגיד לך שאף על פי שלא עשית שמטות עשה יובל לסוף ארבעים ותשע שנה. ופשוטו של מקרא יעלה לך חשבון שנות השמטות למספר ארבעים ותשע:
@9 **והעברת.** לשון (שמות לו ו) ויעבירו קול במחנה, לשון הכרזה: **ביום הכפורים.** ממשמע שנאמר ביום הכפורים איני יודע שהוא בעשור לחדש, אם כן למה נאמר בעשור לחדש, אלא לומר לך תקיעת עשור לחדש דוחה שבת בכל ארצכם, ואין תקיעת ראש השנה דוחה שבת בכל ארצכם, אלא בבית דין בלבד:
@10 **וקדשתם.** בכניסתה מקדשין אותה בבית דין ואומרים מקדשת השנה: **וקראתם דרור.** לעבדים, בין נרצע, בין שלא כלו לו שש שנים משנמכר. אמר ר' יהודה מהו לשון דרור, כמדייר בי דירא ומסחר בכל מדינה וכו' , שדר בכל מקום שהוא רוצה ואינו ברשות אחרים: **יובל הוא.** שנה זאת מבדלת משאר שנים בנקיבת שם לה לבדה. ומה שמה, יובל שמה, על שם תקיעת שופר: **ושבתם איש אל אחזתו.** שהשדות חוזרות לבעליהן: **ואיש אל משפחתו תשבו.** לרבות את הנרצע:
@11 **יובל הוא שנת החמשים שנה.** מה תלמוד לומר, לפי שנאמר וקדשתם וגו' , כדאיתא בראש השנה (ח ב) ובתורת כהנים: **את נזריה.** את הענבים המשמרים. אבל בוצר אתה מן המפקרים, כשם שנאמר בשביעית כך נאמר ביובל, נמצאו שתי שנים קדושות סמוכות זו לזו, שנת ארבעים ותשע שמטה ושנת החמשים יובל:
@12 **קדש תהיה לכם.** תופסת דמיה כהקדש. יכול תצא היא לחלין, תלמוד לומר תהיה, בהויתה תהא: **מן השדה תאכלו.** על ידי השדה אתה אוכל מן הבית, שאם כלה לחיה מן השדה אתה צריך לבער מן הבית, כשם שנאמר בשביעית כך נאמר ביובל:
@13 **תשבו איש אל אחזתו.** והרי כבר נאמר (פסוק י) ושבתם איש אל אחזתו, אלא לרבות המוכר שדהו ועמד בנו וגאלה שחוזרת לאביו ביובל:
@14 **וכי תמכרו** וגו' **.** לפי פשוטו כמשמעו. ועוד יש דרשה מנין כשאתה מוכר, מכור לישראל חברך, תלמוד לומר וכי תמכרו ממכר לעמיתך מכור, ומנין שאם באת לקנות קנה מישראל חברך, תלמוד לומר או קנה מיד עמיתך: **אל תונו.** זו אונאת ממון:
@15 **במספר שנים אחר היובל תקנה.** זהו פשוטו לישב מקרא על אפניו על האונאה בא להזהיר, כשתמכור או תקנה קרקע דע כמה שנים יש עד היובל. ולפי השנים ותבואות השדה שהיא ראויה לעשות ימכור המוכר ויקנה הקונה, שהרי סופו להחזירה לו בשנת היובל. ואם יש שנים מועטות וזה מוכרה בדמים יקרים הרי נתאנה לוקח, ואם יש שנים מרבות ואכל ממנה תבואות הרבה ולקחה בדמים מועטים הרי נתאנה מוכר, לפיכך צריך לקנותה לפי הזמן. וזהו שנאמר במספר שני תבואות ימכר לך, לפי מנין שני התבואות שתהא עומדת ביד הלוקח תמכור לו. ורבותינו דרשו מכאן, שהמוכר שדהו אינו רשאי לגאול פחות משתי שנים, שתעמוד שתי שנים ביד הלוקח מיום ליום, ואפלו יש שלש תבואות באותן שתי שנים, כגון שמכרה לו בקמותיה. ו''שני'' אינו יוצא מפשוטו, כלומר מספר שנים של תבואות, ולא של שדפון, ומעוט שנים שנים:
@16 **תרבה מקנתו.** תמכרנה ביקר: **תמעיט מקנתו.** תמעיט בדמיה:
@17 **ולא תונו איש את עמיתו.** כאן הזהיר על אונאת דברים, שלא יקניט איש את חברו לא ישיאנו עצה שאינה הוגנת לו לפי דרכו והנאתו של יועץ. ואם תאמר, מי יודע אם נתכונתי לרעה, לכך נאמר ויראת מאלהיך, היודע מחשבות הוא יודע. כל דבר המסור ללב, שאין מכיר אלא מי שהמחשבה בלבו, נאמר בו ויראת מאלהיך:
@18 **וישבתם על הארץ לבטח.** שבעון שמטה ישראל גולים, שנאמר (ויקרא כו לד) אז תרצה הארץ את שבתתיה והרצת את שבתתיה, ושבעים שנה שלגלות בבל, כנגד שבעים שמטות שבטלו, היו:
@19 **ונתנה הארץ** וגו' **וישבתם לבטח עליה.** שלא תדאגו משנת בצורת: **ואכלתם לשבע.** אף בתוך המעים תהא בו ברכה:
@20 **ולא נאסף.** אל הבית: **את תבואתנו.** כגון יין ופרות האילן וספיחין הבאים מאליהם:
@21 **לשלש השנים.** למקצת הששית מניסן ועד ראש השנה, ולשביעית ולשמינית, שיזרעו בשמינית במרחשון ויקצרו בניסן:
@22 **עד השנה התשיעת.** עד חג הסכות של תשיעית, שהיא עת בא תבואתה של שמינית לתוך הבית, שכל ימות הקיץ היו בשדה בגרנות, ובתשרי הוא עת האסיף לבית. ופעמים שהיתה צריכה לעשות לארבע שנים, בששית שלפני השמטה השביעית, שהן בטלין מעבודת קרקע שתי שנים רצופות השביעית והיובל, ומקרא זה נאמר בשאר השמטות כלן:
@23 **והארץ לא תמכר.** לתן לאו על חזרת שדות לבעלים ביובל, שלא יהא הלוקח כובשה: **לצמתת.** לפסיקה, למכירה פסוקה עולמית: **כי לי הארץ.** אל תרע עינך בה שאינה שלך:
@24 **ובכל ארץ אחזתכם.** לרבות בתים ועבד עברי, ודבר זה מפורש בקדושין בפרק ראשון (דף כא א) . ולפי פשוטו סמוך לפרשה שלאחריו, שהמוכר אחזתו רשאי לגאלה לאחר שתי שנים או הוא או קרובו, ואין הלוקח יכול לעכב:
@25 **כי ימוך אחיך ומכר.** מלמד שאין אדם רשאי למכור שדהו אלא מחמת דחק עוני: **מאחזתו.** ולא כלה, למד דרך ארץ שישיר שדה לעצמו: **וגאל את ממכר אחיו.** ואין הלוקח יכול לעכב:
@26 **ואיש כי לא יהיה לו גאל.** וכי יש לך אדם בישראל שאין לו גואלים, אלא גואל שיוכל לגאול ממכרו:
@27 **וחשב את שני ממכרו.** כמה שנים היו עד היובל, כך וכך. ובכמה מכרתיה לך בכך וכך. עתיד היית להחזירה ביובל, נמצאת קונה מספר התבואות כפי חשבון של כל שנה. אכלת אותה שלש שנים או ארבע הוצא את דמיהן מן החשבון וטול את השאר, וזהו והשיב את העדף. בדמי המקח על האכילה שאכלה, ויתנם ללוקח: **לאיש אשר מכר לו.** המוכר הזה שבא לגאלה:
@28 **די השיב לו.** מכאן שאינו גואל לחצאין: **עד שנת היובל.** שלא יכנס לתוך אותה שנה כלום, שהיובל משמט בתחלתו:
@29 **בית מושב עיר חומה.** בית בתוך עיר המקפת חומה מימות יהושע בן נון: **והיתה גאלתו.** לפי שנאמר בשדה שיכול לגאלה משתי שנים ואלך כל זמן שירצה ובתוך שתי שנים הראשונים אינו יכול לגאלה, הצרך לפרש בזה שהוא חלוף, שאם רצה לגאול בשנה ראשונה גואלה, ולאחר מכאן אינו גואלה: **והיתה גאלתו.** של בית: **ימים.** ימי שנה שלמה קרויים ימים, וכן (בראשית כד נה) תשב הנערה אתנו ימים:
@30 **וקם הבית** וגו' **לצמיתת.** יצא מכחו של מוכר ועומד בכחו של קונה: **אשר לא חמה.** לו קרינן, אמרו רבותינו זכרונם לברכה אף על פי שאין לו עכשיו, הואיל והיתה לו קודם לכן. ועיר נקבה היא והצרך לכתוב לה, אלא מתוך שצריך לכתוב לא בפנים, תקנו לו במסרת, זה נופל על זה: **לא יצא ביבל.** אמר רב ספרא אם פגע בו יובל בתוך שנתו לא יצא:
@31 **ובתי החצרים.** כתרגומו פצחין, עירות פתוחות מאין חומה. ויש הרבה בספר יהושע (יהושע יג כח) הערים וחצריהם, (בראשית כה טז) בחצריהם ובטירותם: **על שדה הארץ יחשב.** הרי הן כשדות הנגאלים עד היובל ויוצאין ביובל לבעלים אם לא נגאלו: **גאלה תהיה לו.** מיד אם ירצה. ובזה יפה כחו מכח שדות, שהשדות אין נגאלות עד שתי שנים: **וביבל יצא.** בחנם:
@32 **וערי הלוים.** ארבעים ושמנה עיר שנתנו להם: **גאלת עולם.** גואל מיד אפלו לפני שתי שנים, אם מכרו שדה משדותיהם הנתונות להם באלפים אמה סביבות הערים, או אם מכרו בית בעיר חומה, גואלין לעולם, ואינו חלוט לסוף שנה:
@33 **ואשר יגאל מן הלוים.** ואם יקנה בית או עיר מהם: **ויצא ביבל.** אותו ממכר של בית או של עיר וישוב ללוי שמכרו, ולא יהיה חלוט כשאר בתי ערי חומה של ישראל. וגאלה זו לשון מכירה. דבר אחר לפי שנאמר (פסוק לב) , גאלת עולם תהיה ללוים, יכול לא דבר הכתוב אלא בלוקח ישראל שקנה בית בערי הלוים, אבל לוי שקנה מלוי יהיה חלוט, תלמוד לומר ואשר יגאל מן הלוים, אף [לוי] הגואל מיד לוי גואל גאלת עולם: **ויצא ממכר בית.** הרי זו מצוה אחרת, ואם לא גאלה יוצאה ביובל, ואינו נחלט לסוף שנה כבית של ישראל: **כי בתי ערי הלוים הוא אחזתם.** לא היה להם נחלת שדות וכרמים אלא ערים לשבת ומגרשיהם, לפיכך הם להם במקום שדות, ויש להם גאלה כשדות, כדי שלא תפקע נחלתם מהם:
@34 **ושדה מגרש עריהם לא ימכר.** מכר גזבר, שאם הקדיש בן לוי את שדהו ולא גאלה ומכרה גזבר, אינה יוצאה לכהנים ביובל, כמו שנאמר בישראל (ויק' כז) ואם מכר את השדה לאיש אחר לא יגאל עוד, אבל בן לוי גואל לעולם:
@35 **והחזקת בו.** אל תניחהו שירד ויפול ויהיה קשה להקימו, אלא חזקהו משעת מוטת היד. למה זה דומה, למשאוי שעל החמור, עודהו על החמור אחד תופס בו ומעמידו, נפל לארץ, חמשה אין מעמידין אותו: **גר ותושב.** אף אם הוא גר או תושב, ואיזהו תושב, כל שקבל עליו שלא לעבוד עבודה זרה, ואוכל נבלות:
@36 **נשך ותרבית.** חד שוינהו רבנן, ולעבור עליו בשני לאוין: **ויראת מאלהיך.** לפי שדעתו של אדם נמשכת אחר הרבית וקשה לפרוש המנו ומורה לעצמו התר בשביל מעותיו שהיו בטלות אצלו, הצרך לומר ויראת מאלהיך. או התולה מעותיו בנכרי, כדי להלוותם לישראל ברבית, הרי זה דבר המסור ללבו של אדם ומחשבתו, לכך הצרך לומר ויראת מאלהיך:
@38 **אשר הוצאתי** וגו' **.** והבחנתי בין בכור לשאינו בכור, אף אני יודע ונפרע מן המלוה מעות לישראל ברבית ואומר של נכרי הם. דבר אחר אשר הוצאתי אתכם מארץ מצרים על מנת שתקבלו עליכם מצותי אפלו הן כבדות עליכם: **לתת לכם את ארץ כנען.** בשכר שתקבלו מצותי: **להיות לכם לאלהים.** שכל הדר בארץ ישראל אני לו לאלהים, וכל היוצא ממנה כעובד עבודה זרה:
@39 **עבדת עבד.** עבודה של גנאי, שיהא נכר בה כעבד, שלא יוליך כליו אחריו לבית המרחץ ולא ינעול לו מנעליו:
@40 **כשכיר כתושב.** עבודת קרקע ומלאכת אמנות כשאר שכירים התנהג בו: **עד שנת היבל.** אם פגע בו יובל לפני שש שנים, היובל מוציאו:
@41 **הוא ובניו עמו.** אמר רבי שמעון אם הוא נמכר בניו מי מכרן, אלא מכאן שרבו חיב במזונות בניו: **ואל אחזת אבתיו.** אל כבוד אבותיו, ואין לזלזלו בכך: **אחזת.** חזקת:
@42 **כי עבדי הם.** שטרי קודם: **לא ימכרו ממכרת עבד.** בהכרזה כאן יש עבד למכור, ולא יעמידנו על אבן הלקח:
@43 **לא תרדה בו בפרך.** מלאכה שלא לצורך, כדי לענותו. אל תאמר לו החם לי את הכוס הזה, והוא אינו צריך, עדור תחת הגפן עד שאבא. שמא תאמר אין מכיר בדבר אם לצורך אם לאו, ואומר אני לו שהוא לצורך, הרי הדבר הזה מסור ללב, לכך נאמר ויראת:
@44 **ועבדך ואמתך אשר יהיו לך.** אם תאמר אם כן במה אשתמש. בעבדי איני מושל, באמות איני נוחל, שהרי הזהרתני (דברים כ טז) לא תחיה כל נשמה, אלא מי ישמשני: **מאת הגוים.** הם יהיו לך לעבדים: **אשר סביבתיכם.** ולא שבתוך גבול ארצכם, שהרי בהם אמרתי לא תחיה כל נשמה:
@45 **וגם מבני התושבים.** שבאו מסביבותיכם לשא נשים בארצכם וילדו להם, הבן הולך אחר האב, ואינו בכלל לא תחיה, אלא אתה מתר לקנותו כעבד: **מהם תקנו.** אותם תקנו:
@46 **והתנחלתם אתם לבניכם.** החזיקו בהם לנחלה לצורך בניכם אחריכם. ולא יתכן לפרש הנחילום לבניכם, שאם כן היה לו לכתוב והנחלתם אותם לבניכם. והתנחלתם, כמו והתחזקתם: **איש באחיו.** להביא נשיא בעמיו ומלך במשרתיו שלא לרדות בפרך:
@47 **יד גר ותושב.** גר והוא תושב, כתרגומו ערל תותב, וסופו מוכיח ונמכר לגר תושב: **וכי תשיג יד גר ותושב עמך.** מי גרם לו שיעשיר, דבוקו עמך: **ומך אחיך עמו.** מי גרם לו שימוך, דבוקו עמו, על ידי שלמד ממעשיו: **משפחת גר.** זהו הגוי. כשהוא אומר לעקר זה הנמכר לעבודה זרה עצמה להיות לה שמש, ולא לאלהות, אלא לחטוב עצים ולשאוב מים:
@48 **גאלה תהיה לו.** מיד, אל תניחהו שיטמע: **עד שנת היובל.** שהרי כל עצמו לא קנאו אלא לעבדו עד היובל, שהרי ביובל יצא, כמו שנאמר למטה (פסוק נד) ויצא בשנת היובל. ובגוי שתחת ידך הכתוב מדבר ואף על פי כן לא תבא עליו בעקיפין, מפני חלול השם, אלא כשבא לגאל ידקדק בחשבון לפי המגיע בכל שנה ושנה ינכה לו הגוי מן דמיו, אם היו עשרים שנה משנמכר עד היובל וקנאו בעשרים מנה, נמצא שקנה הגוי עבודת שנה במנה, ואם שהה זה אצלו חמש שנים ובא לגאל, ינכה לו חמשה מנים ויתן לו העבד חמש עשרה מנים, וזהו: **והיה כסף ממכרו במספר שנים' כימי שכיר יהיה עמו.** חשבון המגיע לכל שנה ושנה יחשב כאלו נשכר עמו כל שנה במנה וינכה לו:
@51 **אם עוד רבות בשנים.** עד היובל: **לפיהן.** הכל כמו שפרשתי:
@53 **לא ירדנו בפרך לעיניך.** כלומר ואתה רואה:
@54 **ואם לא יגאל באלה.** באלה הוא נגאל, ואינו נגאל בשש: **הוא ובניו עמו.** הנכרי חיב במזונות בניו כישראל:
@55 **כי לי בני ישראל עבדים.** שטרי קודם: **אני ה' אלהיכם.** כל המשעבדן מלמטה כאלו משעבדן מלמעלה:
@56 **לא תעשו לכם אלילם.** כנגד זה הנמכר לגוי, שלא יאמר הואיל ורבי מגלה עריות אף אני כמותו, הואיל ורבי עובד עבודה זרה אף אני כמותו, הואיל ורבי מחלל שבת אף אני כמותו, לכך נאמרו מקראות הללו. ואף הפרשיות הללו נאמרו על הסדר, בתחלה הזהיר על השביעית, ואם חמד ממון ונחשד על השביעית סופו למכור מטלטליו, לכך סמך לה וכי תמכרו ממכר (ויק' כה יד) , מה כתיב ביה או קנה מיד עמיתך (שם) , דבר הנקנה מיד ליד. לא חזר בו, סוף מוכר אחזתו. לא חזר בו, סוף מוכר את ביתו. לא חזר בו, סוף לוה ברבית. כל אלו האחרונות קשות מן הראשונות. לא חזר בו, סוף מוכר את עצמו. לא חזר בו, לא דיו לישראל אלא אפלו לגוי: **ואבן משכית.** לשון כסוי, כמו (שמות לג כב) ושכתי כפי, שמכסין הקרקע ברצפת אבנים: **להשתחות עליה.** אפלו לשמים, לפי שהשתחואה בפשוט ידים ורגלים היא, ואסרה תורה לעשות כן חוץ מן המקדש:
@57 **אני ה'.** נאמן לשלם שכר:

@1 **וידבר יי' אל משה בהר סיני לאמר.** אחשוב כי מפני שהפסיק המאמר בפרשת מקלל שלא היה המאמר בה בהר סיני זכר בה המקום שזה הדבור היה בהר סיני לא אחר דבור פרשת מקלל וזה לאות שכל שאר הדברים הקודמים היו בהר סיני ולזה עמד שם משה רבעים יום וארבעים לילה להגיע לו שם התורה על שלמותה:
@2 **כי תבאו אל הארץ אשר אני נותן לכם וגו'.** מגיד שאין המצוה הזאת נוהגת אלא בארץ ישראל אחר שיבאו בה כלם או רובם וזאת היא השביתה היא שתשבות הארץ מהמלאכה בשביעית בעבודת הארץ והאילנות כמו שיתבאר אחר זה:
@3 **שש שנים תזרע שדך ושש שנים תזמור כרמך.** רוצה לומר תוכל לזרוע שדך ולזמור כרמך ולאסוף תבואתה ולמדנו מזה שכיון שנעשית התבואה באלו השנים נוכל לאסוף ולאכול אותה אפילו בשביעית ואמנם אם לא נעשית התבואה עד בא השנה השביעית הנה יתבאר מזה שלא נוכל לאסוף אותה שנאמר ואספת את תבואתה והיא התבואה ההוא באלו השש שנים:
@4 **ובשנה השביעית שבת שבתון יהיה לארץ שבת להשם.** ר"ל שזאת השביתה תהיה לכבוד השם יתע' כמו הענין בשביתה במועדים הנזכרים במה שקדם כי היא מישרת אל השגתו יתע' כמו שנבאר:
@4 **שדך לא תזרע וכרמך לא תזמור.** ידוע כי הזריעה יותר עצמית בעבודת הארץ משאר העבודות שהם לצרך הזריעה כמו החרישה ולמדנו מזה לפי מה שהתבאר בשרשים הכוללים שעל הזריעה הוא מוזהר לא על החרישה וכן הזמירה שהיא עבודת האילנות היא יותר מועילה לאנשי' בשנה ההיא מפירות הנטיעה כי פירות הנטיעה יאסרו שלש שנים כמו שהתבאר במה שקדם כמו הענין בהרכבה והברכה ולפי שהמכוון בתורה שתשבות הארץ בשנת השמיטה באופן שלא יהיה בעל הקרקע עובד אותה ואוכל תבואתה הנה הזמירה היא היותר ראויה בזה הדין מהנטיעה וההברכה וההרכבה וכל שכן שאר עבודות האילן שהם מועילות לאילן באופן תועלת הזמירה כמו חתיכת הענפים היבשים והחתיכת הנובלת מהאילנות ומה שידמה לזה ולזה לא ינהג זה הדין אלא בזמירה כי אי שם עבודה לאילן מועילה באופן תועלת הזמירה לגפן וזה מבואר בחפוש:
@5 **את ספיח קצירך לא תקצר.** הם הספיחי' העולי' מאליהם בזולת זריעה וזה מבואר מצד הוראת הגדר וראוי שתדע כי דין מה שנזרע בשנה הששית דין הספיחים כי הם גם כן באים ממה שנזרע בשנה הששית באופן מה ואמנם דברה התורה בהווה כי אין בכאן דבר יחייב שיהיה זה הדין יותר ראוי בספיחים וזה מבואר בנפשו וראוי שתדע כי התורה לא צותה שנמנע מלקצור הטפיחים ומבצירת הענבים ההווים בכרם הבלתי נזמר וזה שכבר אמרה והיתה שבת הארץ לכם לאכלה ואם לא נקצור התבואה ולא נבצור הענבים הנה לא יתכן שיהיה לנו לאכלה ולזה יחוייב שתהיה הכונה בזה שלא נקצור אותם כדרך הקוצרים שקוצרים כלל התבואה ולא נבצור כדרך הבוצרים שבוצרים כלל הענבים אבל נקצור ונבצור מהם מעט ויהיה הפקר מה שיהיה בשדות ובכרמי' כמו שהתבאר בפרשת ואלה המשפטים ולזה אמרה התורה בה המקום כאשר ביארה איך תהיה לנו לאכלה ולבהמך ולחיה אשר בארצך תהיה כל תבואתה לאכול להעיר שאין הבעלים זוכין באכילה אלא בעת שנשאר ממנה לחוץ שתוכל לקחת ממנו החיה וכבר יתבאר בפרשת משפטים שכונת התורה בזה כדי שיאכלו ממנה העניים שנאמ' ואכלו אביוני עמך ויתרם תאכל חית השדה וזה גם כן מרה שאפילו העניים לא יהיו רשאין לקצור כל התבואה אבל ראוי שיניחו ממנה לזולתן באופן שתתכן לחית השדה לקחת ממנו:
@5 **ואת ענבי נזירך לא תבצור.** הנה קראה התורה נזירים הגפנים בלתי נזמרים והכונה בזה כמו שקדם שלא יבצור כדרך הבוצרים אבל יבצור מעט מעט באופן שיהיו שאר האנשים מושלים בבצירה מהן כשירצו:
@5 **שנת שבתון יהיה לארץ.** רוצה לומר שלא יעשו בארץ אלו המלאכות הנזכרו' והן הזריעה והקצירה והזמירה והבצירה:
@6 **והיתה שבת הארץ לכם לאכלה.** מגיד שהוא מותר לכל האנשים ואף על פי שאינם עניים והם יקחו מה שיקחו מתבואתה לאכלה לא לעשות בה סחורה כי כונת התורה תראה שהיא תשתדל שישאר מהתבואה ההיא בחוץ באופן שיהיה בה תועלת משותף לכל האנשים ולזה תא התירה התורה לאכול ממנה בבית כי אם בעת שנשאר ממנה לחוץ לחיה כי זהו סבה אל שלא ישתדלו האנשים לקחת ממנה הרבה יחד כי לא יועילו להם אחר שלא ימצא מהתבואות בחוץ בשדות ואלו היה מותר לסחור בפירות שביעית הנה יקחו מהם האנשים הרבה יחד וימהרו לאכלם אם בעיר ההיא או בזולתה ולזה ידמה שלא התירה התורה פירות שביעית לסחורה כי אם לאכילה והוא מבואר שהאכילה תכלול כל מיני הנאה מורגלת תלקח מהפירות בעצמם כמו השתיה והסיכה והצביעה ומה שידלה לזה ממה שתהיה בו ההנאה בפרי בעצמו אלא אם מפני שהתורה זכרה האכילה היא ההנאה היותר חזקה שיתכן שיהיה בדבר הנאכל הנה ראוי שיתבאר מזה שאין ראוי שנשתמש בפירות שביעית בהנאה תהיה הפסד בחק הפרות ההם לפי המורגל ומזה המקום יתבאר שאין ראוי לקצור פרות שביעית כשהן בוסר כי אין זה הפסד ואין זה האכילה הנהוגה בו אלא אם זה היה מעט מעט באופן הנהוג לקחת מהפרות כשהם בוסר ועוד שהתורה אמרה מן השדה תאכלו את תבואתה תהיה כל תבואתה לאכול והתבואה הוא הפירות הנגמרים:
@6 **לך ולעבדך ולאמתך ולשכירך וגו'.** הנה מפני שהתורה התנית שיהיו גרים עמו והם אשר מזונותיהן עליו למדנו שלא יותר לו למכור פרות שביעית כמו שביארנו במה שקדם אלא אם היתה המכירה לאכלה רוצה לומר לקנות ממנה אכל יאכלוהו הוא ואנשי ביתו:
@7 **ולבהמתך ולחיה אשר בארצך תהיה כל תבואתה לאכול.** למדנו מזה שמותר להאכיל פרות שביעית לבהמה אלא שראוי שלא יתנם האדם לבהמתו אם היו ראוים לאדם כי זה הפסד בחק הפרות ההן ואמנם יש לו להניח בהמתו לאכול משם כשהם מחוברין כי הם אינם בזה למטה מהחיה שחוייבנו להניח מכל הפרות מה שיתכן לו לאכל ממנו והוא מבואר שמכירת פירו' שביעית לא יוציא מהם קדושת שביעית כי התורה גזרה בפרות ההם שיהיו לאכלה להם ולאביונים בעת שתוכל לאכול חית השדה מהם לא אחר זה וכן מה שלקח בפירות שביעית הנה עליו קדושת שביעית גם כן עד שלא יוכל להשתמש בו כי אם לאכלה באופן שישתמש מפרות שביעית שנאמר והיתה שבת הארץ לכם לאכלה כמו שביארנו:
@8 **וספרתם לכם שבע שבתת שנים.** רוצה לומר ז' שמטות וזאת הספירה תהיה בשנה השביעית שימנו אז שבת אחת וכן עד שיהיו שבע ורצתה התורה שימנו עם זה השנים שנה אחר שנה מאלו שבע שמטות עד שיהיה מספר השנים מ"ט שנה והנה ענין זה המכפר שוה לענין מספר הימים והשבועו' ממחרת הפסח עד חג השבועות אלא שבכאן עניין נוסף שהשביעית בשנים היא שנת שבתון ואין העניין כן בשבועות הנמנות אחר הפסח:
@9 **והעברת שופר תרועה בחדש השביעי בעשור לחדש.** רוצה לומר אחר תום מ"ט שנה וזה יהיה בשנת היובל לבד שאם היה זה נוהג בכל שמטה ושמטה היתה התורה זוכרת בזאת הפרשה הקודמת שזכר בה דין שנת השמטה ואם היה נוהג זה בכל שנה ושנה היתה התורה זוכרת זה בפרשת אמור אל הכהנים שזכר בה דין המועדים האלו בכללם והנה נתבאר עניין זאת התרועה בפרשת אמור אל הכהנים והתועלת המגיע ממנה ובכלל הנה ביום הכפורים שהוא העשירי משנת החמשים תעשה זאת התרועה כדי שנתן לא לבנו מה שהעיר עליו קדוש שנת החמשים וקדוש העשירי מהימים כי זה יורה על ענין נפלא בחכמת האלהות כמו שהתבאר מדברינו במה שקדם וכבר התבאר שזה המנין בענין השמטות והיובל אינו נוהג אלא בארץ שכבר אמר בראש זה הענין כי תבואו אל הארץ. וראוי שתדע שזה הענין לא ינהג כי אם אחר שירשו הארץ וחלקו אותה שנאמר שש שנים תזרע שדך ושש שנים תזמור כרמך עד שחלק הארץ אין אני קורא בו שדך וכרמך. וראוי שלא יעלם ממנו שזאת הספירה היא בהכרח מיוחסת לבית דין הגדול כמו העניין מבקדוש החדש וגם כן הנה מפני שהשנה נכנסת בהכנסת החדש והיה קדוש החדש מיוחד לבית דין הגדול כמו שביארנו בפרשת בא אל פרעה הנה קדוש השנה ההיא מיוחס בהכרח להם וזה בלתי צריך אל ביאור:
@10 **וקראתם דרור בארץ לכל יושביה.** הנה ביאר שזה החירות שיסור אז מכל אחד מיושבי הארץ הממשלה שתהיה לזולתו עליו ועל אחזתו. רוצה לומר שאם מכר עצמו או שדהו יצא לחפשי בבא היובל וישוב אליו שדהו כמו שהתבאר אחר זה והנה קרא שנה הזאת יובל שהוא שב אל הקרן אשר בו יתקעו שנאמר במשוך היובל במשוך קרן היובל להעיר על התרועה הנעשית בה שישימו לב עליה על מה שהיא בזאת השנה ובזה היום שהיא בו ולפי שאמר לכל יושביה והיה מבואר שהמתוארים שהם יושביה הם כל השבטי' איש על מקומו אשר הגיע לו בגורל בעת חלוקת הארץ למדנו שאם אין כל יושביה עליה אין היובל נוהג וכן אם היו שם והיו מעורבבים לפי שאין השבט יושב בנחלתו ואין היושבין בארץ יושבים על דרך האמת לפי מה שהתבאר מהשרשים הכוללים וגו':
@11 **יובל היא שנת החמשים שנה תהיה לכם.** למדנו מזה שעבודות הארץ האסורות בשביעית אסורות ביובל ולא הזכיר בכאן איסור הזמירה כי הוא דומה לזריעה ועוד כי כבר רמז אליו במה שאמר ולא תבצרו את גזיריה כי זה מורה שלא יהיו הגפנים נזמרים בשנה היא ולזה יקראו גזירים כי יגזרו מהם האנשים אז ולא יעבדו אותם:
@12 **כי יובלו היא קדש תהיה לכם.** ראוי שתדע כי אין רצון התורה בזה שיהי קדש כי אם לענין שיאכלו מן השדה את תבואתה ולא יאספוה לביתם וזה אמנם היה כדי שיהיו כל האנשים שוים באוכל השנה ההיא כמו הענין בשנת השמיטה וזהו עניין קדושת פירות שנת היובל כי בבא הזמן שלא ימצא מהם בשדה יאסרו הנמצא בבית ושלא יותר להם לאספם אל ביתם כדרך הקוצרים והבוצרי':
@13 **בשנת היובל הזאת תשובו איש אל אחוזתו.** ר"ל אם מכרו אות':
@14 **וכי תמכרו ממכר לעמיתך.** לפי שמגדר הונאה יתבאר שהיא אינה נוהגת כי אם בדברים שיתכן שיהיה ידוע ערכם ומוגבל הנה הוא מבואר שאין אונאה בקרקעו' כי תבואותיהם בלתי מוגבלי' וידועים בעצמות באופן שנוכל לשפוט שתהיה שם אונאה כי הקרקע כחיי על פירות אין להם תכלית ועל פירות שונים יתחלף ענין הערך בהם מאד וכן הוא מבואר שאין אונאה בעבדי' כי לא יגרע התועל' שאפשר שיגיע מעבודתו ועצתו ויתבאר שאין אונאה בשטרות כי אין לשטר מצד עצמותו שום ערך אלא מצד שבסכתו יגבה המלוה את חובו או יהיה לו ראיה על מה שכלל אותו השטר ההוא ובכלל הנה כמו שדברי העדי' אין להם ערך כי אם לראיה לבד כן הענין בשטרות ולזה הסכימו רז"ל שהאונאה הנזכרת בזה הפסוק הוא המטלטלים וביארו זה ממה שאמר או קנה מיד עמיתך כי זה הלשון יתכן שיפול במטלטלין לא בקרקעות כי אינם נעתקים מיד המוכר לקונה והנה יתבאר שאין אונאה להקדש ממה שאמר אל תונו איש את אחיו והוא מבואר כי במטלטלין יש אונאה כי ענינה מוגבל וידוע אלא שכבר יתבאר כי למטה משתות אין שם אונאה לפי שדרך האנשים לתת בדבר שירצו אותו מאד לקנותו יותר מכדי שוויו עד שתות ולא יקפיד בזה וזה מבואר מן החוש וכן אם יש לנו הוראה שנתרצה בזה המקח עם ידיעתו שקנ' אותו יותר מכדי שוויו הרבה אין בו אונאה ואפילו לקח שוה דינר באלף דינר כי כמו שהאדם שליט לתת מתנה כן הוא שליט לתת במסחר יותר משוויו לרצותו בו ואולם עניין האונאה הזאת תהיה במה שחשב שיהיה ערך הדבר יותר ממה שהוא או פחות ומפני זה נתרצה לתת יותר בו או לתתו לפחות וראוי שתדע שזאת האונאה נתנה לחשבון ובזה האופן תסור כי הוא מונה אותו כל זמן שלא החזיר לו שיעור האונאה ולפי שלפי הנהוג אין ההוקרה והוזלה במסחרים בין האנשים בכמו אלו הדברים יותר משתות הנה אם היתה באונאה יותר משתת לא יחוייב שישאר המקח קיים אבל יהיה כאלו אין שם מקח ואמנם אם היה שתות יתקיים המקח ויחזיר האונאה ופחות משתות לא יחוייב להחזיר אונאה כמו שביארנו והנה עכ"פ נכלל בזה הפסוק שלא להונות בעניין הקרקעות כי התורה מדברת בזה המקום בקרקעות והנה האונאה שהזהירה עליו לפי מה שאחשוב הוא שלא יונה אותו במנין השנים אשר עד היובל וימכור לו מפני זה שדהו יותר ממה שראוי או יקנה אותו פחו' ממה שראוי וזה כי מפני שקנין הקרקעו' חוזר ביובל הנה ערכו יותר מעט בכל מה שקרבה שנת היובל ולזה אם הונהו והביאוהו לחשוב כי אין עד היובל כי אם מעט זמן ויש שם זמן יותר ארוך או הפך זה הנה תהיה בזה אונאה מזה הצד כי הוא אינו מוכר לו כי אם מספר שני תבואות אף על פי שהוא מוכר לו שדהו במוחלט והנה הטעהו במספר בענין הזה ולזה ביאר אחר זה שזה האופן מהאונאה יקרה בקרקעות מצד היובל ועליו הזהיר ובכלל הנה בקרקעות אפשר שתהיה אונאה מצד המספר או מצד המדה והאונאה אשר מצד המד' כבר הזהיר עליה באמרו לא תעשו עול במשפט במדה כמו שבארנו שם והאונאה אשר תהיה מצד המספר הזהיר עליה בזה המקום:
@15 **במספר שנים אחר היובל תקנה מאת עמיתך.** ר"ל כי מפני שהקרקע חוזר ביובל הנה אין נקנה לו אלא במספר שני' ולזה ראוי שיהיה הערך לפי השני' אשר עד היובל אם הרבה הרבה אם מעט מעט כמו שזכר בפסוק הבא אחר זה ולמדנו ממה שאמר אחר היובל שאין הקרקע נקנה ביובל וראוי הוא להיות כן כי הנמכר חוזר כ"ש שהוא ראוי שלא ימכר ביובל ולפי שאמר במספר שנים למדנו שאין הקרקע נקנה לצמיתות בפחות משתי שנים ואיננו נמכר גם כן בזה האופן לפחות משתי שנים שנאמר מספר שני תבואות ימכור לך וראוי היה להיו' כן כי התור העתיקה הממכר למספר שנים בלתי בעל תכלית אל מספר מוגבל אינו יותר ממ"ט שנה וראוי שלא יהיה נעתק אל מה שאינו מספר והוא האחד והמעט שיפול בו שם המספר הוא שנים ולזה לא יהיה נמכר בזה האופן בפחות משתי שנים וראוי שיהיו אלו שתי השנים שנים ראויים לתבואות שנאמר שני תבואות ולזה אם היתה אחת מהשנים בלי ראויה לתבואה מצד עצמותה כמו שהיתה שנת שביעית או שנת שדפון אינה עולה לו מן המנין ומזה המקו' נלמד שאף על פי שיש רשות למוכר לגאל שדהו כמו שנתבאר אחר זה הנה אינו גואל אלא אחר שנשארה ביד הקונה שתי שנים ראויות לתבואות:
@16 **לפי רוב השנים תרבה מקנתו.** הנה רמז בכאן אל איכות האונאה שהזהיר ממנה בפסוק הקודם:
@17 **ולא תונו איש את עמיתו וגו'.** הנה זאת האונאה היא אפילו בזולת מכר וקנין כמו אונאת דברי' ולזה לא זכר קודם לא מכר ולא קנין כמו שעשה זה באונאת הקודם:
@18 **ועשיתם את חקותי ואת משפטי תשמרו ועשיתם אותם.** אמר עשייה לחוקים ולא זכר בהם שמירה שהיא זכירתם בלב כי היה אפשר שיחשוב חושב שלא תצטרך בהם עשייה אבל יספיק שנזכיר עניינם בלב כדי שנעמוד על ההערה אשר בחקי' ההם כי יראה שעשייתם היא לזה התכלי' כמו שהתבאר בדברינו ולזה הוצרכה התורה לצוות בעשייתם ואמנם במשפטים והם המצוות המכוונים בעצמותם ויחייבם השכל לפי שכבר יחשב שלא יצטרך לנו למודם אבל יספיק שנעשה אותם הנה ולזה צותה התורה לזכור אותם בלב כי יהיה סבת העשייה כמו שאמרו ז"ל שהתלמוד מביא לידי מעשה:
@18 **וישבתם על הארץ לבטח.** ר"ל שלא תגלו מן הארץ אבל תשבו עליה לבטח ולא תפחדו משום דבר:
@19 **ונתנה הארץ פריה ואכלתם לשובע.** כבר בארנו בספר מלחמות ה' כי גם באלו הענינים יהיו מושגחים הדבקים בשם יתעלה וכי תאמרו מה נאכל בשנה שביעית ידוע שזה המאמר יתכן שיפול בכל שמטה ושמטה כי יצטרך שתספיק להם התבואה מהשנה השישית לשתי שנים ויותר ממה שתפול זאת המבוכה היא השמיטה אשר יבא אחרי' היובל כי יצטרך שתספיק אז תבואה השנה הששית לשלש שנים ועליו אמר וצויתי את ברכתי לכם בשנה הששית ועשת את התבואה לשלש השנים ואפשר שנאמר שהוא היותר נכון שזה הפסוק נאמר על כל שנת השמטה והנה תעשה התבואה לשלש השנים שכבר יאכלו ממנה בשנה הששית מעת בא תבואתה ועוד כי בה יזרעו מהבואה ההיא בשנה השמינית וזהו מה שאמר וזרעתם את השנ' השמינית ואכלתם מן התבואה ישן. ר"ל שכבר תספיק עוד התבואה ההיא לזרוע ממנה בשנה השמינית ולאכול ממנה ישן עד בא תבואת' ואמנם מה שאמר אחר זה עד השנה התשיעית עד בא תבואתה תאכלו ישן הוא שב לשנת השמטה שבא אחריה היובל:
@23 **והארץ לא תמכר לצמיתות.** זו היא מצות לא תעשה וכבר בארה התורה שלא יועילון לו אם מכרה לצמיתת שהרי היא חוזרת לבעליה ליובל:
@23 **כי לי האץ כי גרים ותושבים אתם עמדי.** ר"ל הנה שלי הארץ ולא השלטתי אתכם בה למכרה לצמיתת אף על פי שאתם מחזיקים בה כי אתם כמו גרים בארץ ההיא או כמו תושב שהוא ביד אדוניו שאין לו שולטנות במה שהוא מחזיק בו כטעם תושב כהן ושכיר לא יאכל בו:
@24 **ובכל ארץ אחוזתכם גאולה תתנו לארץ.** ר"ל שלא די שהארץ לא תמכר לצמיתות ותצא ביובל אבל יחוייב עוד שתתנו גאולה לארץ שאם מכרה אדם מכם ורצה לגאול אותה יהיה שליט בזה ולא יוכל הקונה למחות בידו וכבר יתבאר זאת הגאולה איך תהיה בפרשה הבאה:
@25 **כי ימוך אחיך ומכר מאחוזתו.** למדה תורה דרך ארץ שאין ראוי למכור אחוזתו אם לא יביאהו לזה הכרח וזה כי קנין קרקעותיו הוא יותר קיים משאר הקניינים אשר יהיו מחירו ואמר מאחוזתו להעיר כי כשיוכרח על זה לא ימכור ממנו אלא קצתו ויניח קצתו להסתפק בו:
@25 **ובא גואלו הקרוב אליו וגאל את ממכר אחיו.** למדנו שהיותר קרוב מגואליו קודם לזה הענין:
@26 **ואיש כי לא יהיה לו גואל והשיגה ידו ומצא כדי גאולתו.** ר"ל אם לא מצא אחד מקרוביו שיגאל את ממכרו והשיגה ידו משלו לגאול הנה הרשות בידו ולמדנו מזה שאין ראוי שימכר במקום אחד לגאול זה הקרקע ולא שילוה סך גאולתו שנאמר והשיגה ידו ולפי שאמר ומצא כדי גאולתו. למדנו שאינו גואל לחצאין אבל גואל את כלו או תשאר בידו הקונה עד היובל:
@27 **וחשב את שני ממכרו והשיב את העודף לאיש אשר מכר לו ושב לאחוזתו.** למדנו שאין ראוי לגאל עד שיאכל הקונה קצת התבואות שנאמר והשיב את העודף וממה שקדם נתבאר שהוא ראוי שיאכל הקונה שתי שנים קודם שישלוט המוכר לגאל ולמדנו ממה שאמר שני ממכרו שאם היו לו עשר שנים ראוים לתבואות עד היובל ואכל מהם הלוקח ב' מהם הנה יחשוב לכל שנה מהשנים הנותרות עשירית המקח. ואף על פי שאכל הלוקח שלש תבואות בשני שנים או שני תבואות בשלש שנים אין מונין לו למספר תבואות אבל מונין לו למספר שנים ולמדנו ממה שאמר לאיש אשר מכר לו שאם מכרה לאחר ומכרה האיש ההוא לאיש אחר בסך יותר גדול אינו מחשב אלא לפי הסך שמכר ראשון וזה מבואר גם כן מצד אחר כי מפני שלא השליטהו השם יתעלה למנוע המוכר מלגאול הנה אין לו רשות למכרו לאחר בסך יותר גדול להכביד עניין גאולת המוכר ואולם אם מכרה בפחות כיון שנסתלק ממנה הקונה הראשון הנה יגאל האדון מיד הקונה השני לפי מה שקנה כי אין לו זכות בזה הקניין יותר מזה השיעור אף על פי שקנהו מיד הבעלים ולדנו ממה שאמר ושב לאחוזתו שאם השביח הקונה הקרקע חייב המוכר להחזיר לו השבח כי אין השבח אחוזתו אבל המציאו הלוקח:
@28 **ואם לא מצאה ידו די השיב לו והיה ממכרו ביד הקונה אותו עד שנת היובל.** למדנו מזה גם כן שאין בידו ללוות ולגאל ולמכור ולגאל ולמדנו גם כן שאין השבח חוזר ביובל שנאמר והיה ממכרו ביד הקונה אותו עד שנת היובל ויצא ביובל ושב לאחוזתו ממכרו יוצא ביובל ולא שבה ולזה יחוייב שיחזיר לו השבח:
@28 **ויצא ביובל ושב לאחוזתו.** למדנו שהמוכר אילנו' אינם חוזרי' ביובלים כי אינם אחוזה ואמנ' הקרקע חוזר כי הוא אחוזה:
@29 **ואיש כי ימכור בית מושב עיר חומה.** לפי שאילו המצות תלויות בארץ כמו שהתבאר בראש העניין והיה מבואר מן השרשים הכוללים כי התארים הנזכרים בתורה אינם לפי המציאות אבל לפי מה שראוי שיתואר בו בעל התואר ההוא הנה למדנו כי מה שיתואר כשהוא עיר חומה בעת כבוש הארץ אף על פי שאחר זה לא יהיה מוקף חומה דינו דין ערי חומה והוא מבואר שעיר חומה הוא מה שהוא מוקף חומה ואחר כך נתיישב העיר בתוך החומה לא מה שהיה עיר תחלה ואחר כך הוקף חומה והוא מבואר שאם אין מה שמוקף חומה במדרגת עיר לא ינהג בה זה הדין וראוי שתדע כי הבתים יכללם החצר כי ימצאו בתים רבים בחצר אחד והעיר תכלול חצרות ובתיהם ואם לא היה בעיר חצרות רבים והם על המעט שלשה יכלול כל אחד מהם בתים לא ינהג בה דין ערי חומה וכן אם לא היה הבית תוך עיר החומה שנאמר וקם הבית אשר בעיר וכן אם לא היה בבניין ההוא דין הבית כמו שיהיה שדה או שלא היה כשיעור בית לא ינהג בו זה הדין אבל דינו דין שאר הקרקעות שחוזרי' ביובל:
@29 **והיתה גאולתו עד תום שנת ממכרו.** ידוע ממה שקדם בפרשת בא אל פרעה כי השנה היא פעם שתים עשרה חדש ופעם י"ג חדש ולזה היתה גאולתו מיום החדש ההוא עד כמו יום החדש ההוא מהשנה האחרת והמשל שאם נמכר באחד באדר תהיה גאולתו עד אחד באדר מהשנה האחרת שנא' עד מלאת לו שנה תמימה ולפי שלא התנה בכאן שתשיג ידו לגאל למדנו שיש לו למכור קרקע אחר לגאל וראוי היה להיות כן כי מפני שהבית הזה נחלט ואין העניין כן בשאר הקרקעות הנה יועיל לו אם ימכור במקום אחר לגאל אותו ואמנם אין בידו לגאל אותו חציין שנאמר גאולתו לא גולת קצתו ויתבאר שאין בידו ללות מעות לגאל אותו כי התורה לא הרשית קרוביו לגאל אותו כ"ש שאין ראוי שיגאלוהו מי שינם קרוביו ואלו היה אפשר לו ללות מעות לגאל אותו היה נגאל על יד מי שאינם קרוביו במעות שילוה מהם:
@29 **ימים תהיה גאולתו.** ר"ל שנה אחת כי הוא כמו יום ארוך כמו שהתבאר בחכמה הטבעית וראוי שתדע שלא יגרע מערכו דבר בעבור מה ישב בו הקונה אותו כי לא אמרה התורה שיחשב בזה דבר ועוד כי זה המכר הוא לדורות לאין תכלית ולזה לא יכול לגרוע ממנו דבר בעבור מה שישב בו מהשנה וזה מבואר בנפשו:
@30 **ואם לא יגאל עד מלאת לו שנה תמימה.** ר"ל מיום ליום:
@30 **וקם הבית אשר בעיר וגומ'.** למדנו מזה שאם לא נגאל תוך שנה שלמה באופן הנזכר הנה הוא מוחלט לקונה אותו. ר"ל שאינו יוצא ביובל ולפי שאמר לדורותיו למדנו שאם היה קונה הבית באופן שאין לו דורות כמו ההקדש הנה אינה מוחלט אמנם גאלו אחד מן ההקדש הנה הוא מוחלט במלאת לו שנה תמימה:
@31 **ובתי החצרים.** הם בתי העיירות אשר אינם מתוארות בשהם בתי ערי חומה והנה דינם כדין השדות לעניין הגאולה ולצאת ביובל כמו שזכר:
@32 **וערי הלויים בתי ערי אחוזתם גאולת עולם תהיה ללויים.** למדנו שהלויים גואלים באיזה עת שירצו אף על פי שלא היה שתי שנים ביד הקונה אותו:
@33 **ואשר יגאל מן הלויים.** למדנו מזה שמי שהוא מהלויים אף על פי שאינו לוי כמו שהיה בן בת לוי דינו בעניין הגאולה כדין הלויים והנה הרצון בזה גולת עולם תהיה ללויים ולאשר יגאל מן הלויים:
@33 **ויצא ממכר בית ועיר אחוזתו ביובל.** ר"ל שאם לא גאל ממכרו הנה הוא יוצא ביובל:
@33 **כי בתי ערי הלויים היא אחוזתם בתוך בני ישראל.** ר"ל שכבר יחוייב שיהיה ללויים חירות נוסף בזה העניין על שאר ישראל כי בתי עריהם היא בתוך בני ישראל כי אין להם נחלה בארץ כמו שנזכר בתורה אבל נתן להם כל אחד מהשבטים מחלקו ואם יקרה שימכרו בתיהם יתכן שיקנו אותם אנשי השבט שהיו אלו הערים מהם ובתוך נחלתם ויקרה מזה באורך הזמנים שתסוב נחלת הלויים לשאר השבטים ואולם בשאר שבטים לא יתכן שיקרה זה כי אנשי השבט יושבים בנחלתם ואם יקרה שימכור אחד מהם ביתו יקנהו אחד מאנשי השבט להיותם יושבים לבדם בארץ הוא:
@34 **ושדה מגרש עריהם לא ימכר כי אחוזת עולם הוא להם.** ראוי שתדע שאין הרצון בזה שלא ימכר כלל כי כבר בארה התורה כי גם בתיהם יש להם רשות למכרם אלא שיש לבתיהם גאולת עולם ואמנם הרצון בו שלא ישנו אותו לעשות שדה מגרש או הפך או מגרש עיר או הפך והה הושאל לזה העניין שם המכירה לפי שהמכירה ישתנה בה רשות בעל הקניין וישוב אל בעלי' אחרים ולזה הושאלה המכירה להשגות הקניין מן ההשתמשות לתכלית אחת אל השתמשות לתכלית אחרת ואמר אשר התמכר לעשות הרע. ר"ל שבאופן שהיה מיוחד לעשיי' הטוב בכמו האופן ההו' שב לעשות הרע כאלו יצא מרשות המנהיג הטוב אל רשות המנהיג הרע ומזה העניין השני נקרא בזה המקום מכירה העשיי' מהשדה מגרש או הפך ומה שידמה להם כי השתמשו בו לתכלית מקבלת אל התכלית אשר כוון בה ולזה אמר כי אחוזת עולם הוא ללויים ולזה אין ראוי לשנות אותו מענינו כי בזה האופן המשוער יאות להשתמש בו לעולם באופן שלם ואם ישתנה זה הסדר יפסד היישוב ההוא ויבלבל עניינו והמשל שאם עשה המגרש עיר או השדה מגרש לא יספיק להם ולבהמתם ולכל חייהם ואם עשו הפך זה ימעיטו יישוב המקום ההוא וכבר הקפידה התורה באלה מסעי שישתמשו הלויים באלו המקומות בתכלית המכוון להם ולא יעתיקום אל תכלית אחר אמר והיו הערים להם לשבת ומגרשיהם יהיו לבהמתם ולרכושם ולכל חייתם:
@35 **וכי ימוך אחיך ומטה ידו עמך והחזקת בו.** ר"ל שאם היה אצלך ראוי שתחזק בו להיטיב לו מהונך:
@35 **גר תושב וחי עמך.** ר"ל גר צדק או שהיה גר תושב את ראוי להחיותו עמך לא שתחיהו ותמית עצמך כי חייך קודמים ולזה גם כן זכרה התורה זה העניין בהדרגה וזכרה תחלה אחיך ואחר כך גר צדק ואם הוא גם כן אחיך אלא שאינו מזרע ישראל ואח"כ גר תושב:
@36 **אל תקח מאתו נשך ותרבית ויראת מאלהיך.** למדנו שזאת האזהרה אינה אלא במי שהוא אחיך כמו הישראל וגר צדק וכבר זכרה זה התורה במקום אחר אמר לנכרי תשיך ולאחיך לא תשיך וזה ראויה שלא הזהירה התורה מלקיחת נשך ותרבית אלא ממי שהוא אחיך וראוי שתדע כי בהלואת כסף יפול שם נשך כאלו תאמ' אם הלוה ארבע דנרין בחמש כי כמו שהנושך נשך דבר מחוץ כן העניין במי שמלוה כספו ברבי' כי אין מדרך הכסף לעשות פירות מעצמותו ובהלואת האוכל יפול שם מרבית אם ירבו בו שנ' את כספך לא תתן בנשך ובמרבית לא תתן אכלך משל נתינת האוכל מי שילוה ארבע סאין בחמש והוא מבואר שהעובר על אלו האזהרות יחוייב להשיב מה שלקח מנשך ותרבית כי כל עת שהוא מחזיק בו הוא לוקח מאתו נשך ותרבית:
@36 **ויראת מאלהיך וחי אחיך עמך.** אמר ויראת מאלהיך שלא תערים בזה שלא תתלה מעותיך בגוי כדי לקחת רבית מישראל ואמר וחי אחיך עמך שתחוייב להלוות לו כדי שיהיה עמך כמו שאמר אם כסף תלוה את עמי את העני עמך. ואולי לה אמר ויראת מאלהיך שאף על פי שלא תוכל לקחת תועלת בהלוואתך לעני אל תמנע מזה אבל השתדל שייה עמך. ואולם חייך קודמין ולזה אמר עמך:
@38 **אני יי' אלהיכם אשר הוצאתי אתכם מארץ מצרים לתת לכם את הארץ.** הטוב ומשלי תטיבו לעניים והנה הנחלתי לכם אלו הטובות שתתנהו בהם באלו התנאים שצויתי אתכם:
@38 **להיות לכם לאלהים.** רוצה לומר שאין ראוי שיכבד לכם מה שאגזור עליכם מההטבה לעניים אני הוא שהוצאתי אתכם מתכלית הדלו' לתת לכם הארץ הטובה:
@39 **וכי ימוך אחיך עמך ונמכר לך.** מגיד שאין ראוי לאדם למכור עצמו אם לא היה זה בסבת עוני וראוי גם כן שימכר לך כשיביא ההכרח לזה לא לנכרי ולזה הקדימה התורה המכרו לישראל קודם המכרו לנכרי:
@39 **לא תעבוד בו עבודת עבד.** ר"ל שלא יבזהו לקחת ממנו השירות שיקחו מהעבד הכנעני בחליצת מנעליו ומה שידמה להם מהעבודות הבזויות:
@40 **כשכיר כתושב יהיה עמך.** ר"ל שעניין עבודתו ממוצע בין עבודו' השכיר והתושב כי השכיר למעט זמן שכירתו לא יעבוד כי אם העבודה המיוחדת אשר שכרוהו לעשותה והתושב הוא הפך זה כי הוא מוכן לכל העבודות שירצה רבו והעבד העברי ממוצע בין שתי אלו העבדיות כי הוא לא ייוחד לעבודה מיוחדת כמו העניין בשכיר ולא לכל העבודות כמו הענין בתושב והוא מבואר שהמוכר עצמו יש לו מכור עצמו משש שנים לא נאמר שש שנים אלו בעבד עברי שמכרוהו ב"ד כמו שנתבאר בפרשת ואלה המשפטים ומה שאמר עד שנת היובל יעבוד עמך לא יחויי' שלא יוכל למכור עצמו בפחות מה הזמן אבל התחייב ממנו שלא יוכל למכור עצמו ליותר מזה הזמן:
@41 **ויצא מעמך הוא ובניו עמו.** למדנו שהקונה עבד עברי חייב במזונו' בניו והיה זה כן לפי שהוא חייב לזון את בניו כמו שבארנו בפרשת ואלה המשפטים וכל שכן שיחוייב במזונות אשתו כי כבר נתבאר בתורה התחייב האדם במזונות אשתו:
@41 **ושב אל משפחתו וגו'.** למדנו מזה שכל עבד שיוצא ביובל הוא שב אל משפחתו לחזקה שהיה בה ולזה אם היה העבד עברי כהן שמכרוהו ב"ד אינו נרצע שאם היה נרצע לא היה שב לחזקה שהיה בה כי הוא בעל מום ופסול לעבודה. ואמר ואל אחוזת אבותיו ישוב ללמד שאין ראוי לאדם למכור עצמו אם לא אחרי שלא נשאר לו מאחוזתו דבר למכור:
@42 **כי עבדי הם אשר הוצאתי אותם מארץ מצרים.** ר"ל כי מפני שהיו עבדים במצרים והוצאתי אותם משם הנה הם עדי ולזה לא ישלטו להמכ' לעבדים יותר מה הזמן וג"כ הנה קניתי אותם לעבדים במה שהראיתי להם מאותותי ונפלאותי בהוציאי אותם מארץ מצרים ואם ימכרו לעבדים עולמית הנה יסירו עול עבודתי מל צוארם:
@42 **לא ימכרו ממכרת עבד.** ר"ל שלא ימכרו עולמית כהמכר עבד כנעני ושלא ימכרו על אבן הלקח כמכור העבדים השבויים:
@43 **לא תרדה בו בפרך.** ר"ל שלא תכוין בעבודתו לענות גופו אבל תכוין בה לעשות מה שיצטרך לך ולזה אין ראוי לאדם שיצוה לעבדו העברי לעשות מלאכה והוא בלתי צריך כדי שלא ישב בטל ולזה אמר ויראת מאלהיך כי השם יתעלה הוא היודע כוונתך בזה:
@44 **ועבדך ואמתך אשר יהיו לך מאת הגוים אשר סביבותיכם.** ר"ל שהעבד והאמה יהיו לך ותמשו' בהם כחפצך הם מאת הגוים אשר סביבותיכם והם הכנעניים:
@44 **מהם תקנו עבד ואמה.** ר"ל שמהם תוכלו לקחת לקנות עבד ואמה קנין עולמים באופן קניין עבד שנקנה על אבן הלקח:
@45 **וגם מבני התושבים הגרים עמכם מהם תקנו.** שלא יחשוב שהותר זה באלו האומות שאינם גרים עמכם מצד שאינם מקיימים המצות שנצטוו בני נח ואמנם אשר הם גרים עמכם מהם לא יותר בהם זה להיותם מקיימי' המצות ההם ולזה הוצרך לבאר שכבר הותר זה גם בגרים עמכם וממשפחתם אשר עמכם הם אשר נולדו מהכנעניות ומזולתם מן האומות כי הנולדים הם ממשפחת האם אשר הולידו בארצכם הם הבנים שהולידו הכנענים מנשי שאר האמות כי האבות הם המולידים:
@45 **והיו לכם לאחוזה.** למדנו מזה המקום שקניין עבד הכנעני דומה לקניין האחוזה בתאר איכות הקניין והנה נתבאר בפרשה הבאה שקנין האחוזה יהיה בכסף ולזה יתבאר שקנין העבד הוא בכסף והתבאר מפרשת שפחה חרופה שהעבד קונה עצמו בשטר ולזה יחוייב שיהיה נקנה גם כן בשטר ויתבאר שהוא נקני' בחזקה לפי שהאחוזה נקנית בחזקה כמו שנזכר בכרם נבות:
@46 **והתנחלתם אותם לבניכם אחריכם לרשות אחוזת עולם.** זכר הבנים כי הם היותר ראויים ליירש וזה כי הבנות לא ינחלו אלא כאשר אין שם בן:
@46 **לעולם בהם תעבודו.** ידמה מהנמשך לה שהרצון בזה שראוי לנו לעבוד בעבד כנעני אף על פי שאין העבודה צריכה לנו ואין העניין כן בעבד עברי שהיה עובד ולזה אמר שבאחינו בני ישראל לא נרדה בפרך:
@47 **וכי תשיג יד גר ותושב עמך.** הגר הוא גר צדק ותושב הוא הדר בארצנו שקבל עליו שלא לעבוד ע"ז כי לא נניח לשבת בארצנו העובד ע"ז שנאמ' לא ישבו בארצך פן יחטיאו אותך לי:
@47 **או לעקר משפחת גר.** אחשוב כי עקר הוא הפך תושב ולפי שהתושב הוא שאפשר לו לשבת עמנו בארצנו לפי שאינו עובד ע"ז הנה יהיה עקר מי שיחוייב לנו לעקור אותו ולהעתיקו מארצנו לפי שהוא עובר ע"ז והנה הוא משפחת גר תושב אלא שגר תושב קבל שלא לעבוד ע"ז והוא לא קבל עליו זה:
@48 **אחרי נמכר גאולה תהיה לו עד או השיגה ידו ונגאל.** ר"ל שאין ראוי לעזוב אותו בידו שלא ילמד ממעשיו ולזה ראוי להשתדל בגאולתו היותר קרוב לו כמו אחיו או דודו או בן דודו או שאר קרוביו וזה בהדרגה כי היותר קרוב הוא קודם לגאולה ואם אין אחד מקרוביו גואלו הנה ישתדל הוא עצמו בגאולתו תכף שתשיג ידו ולפי שלא אמר ומצא כדי גאולתו כמו שאמר בפרשת הקודמת למדנו שהוא נגאל לחצאין. ר"ל שאם השיגה ידו לגאל הוא עצמו לקצת שוויו גואל עצמו לקצת שוויו. ובכלל הנה בארה התורה שראוי להשתדל שלא יהיה נשקע שם ולזה צותה התורה שיגאלו אותו קרוביו ומפני זה הוא מבואר שיש בידו ללוות או לגאל עצמו או למכור מנכסיו או לגאל עצמו לחצאין:
@50 **וחשב עם קונהו משנת המכרו לו עד שנת היובל.** אמר זה לפי שהוא אינו מחויב לעבוד כי אם קונו ולזה אם מת אדוניו אינו עובד את הבן וזה הדין הוא משותף לגר צדק ולתושב ולעקר כי בהם דברה זאת הפרשה:
@50 **והיה כסף ממכרו במספר שנים כימי שכיר יהיה עמו.** למדנו שהוא נגאל בכסף לא בשוה כסף ולזה זכרה התור' בזה המקו' כסף ולא זכרה זה בפרשת מוכר שדה אחוזה וזה מיושר התור כי מפני שהקלה התורה בעניין הגאולה הזאת שיגאלוהו קרוביו או ילוה לגואל או יגאל עצמו אם תשיג ידו הנה יקרה בזה מן העול אם יוכל לתת לאדוניו שוה כסף והוא שבזה האופן יתכן שיערימו האנשים לימכר מה שלא ימצא לו קונין לקנות ויהיה בזה עשוק מי שיקנה זה העבד ולזה לא רצתה התורה שלא יגאל אלא בכסף לא בשוה כסף ומה שאמר כימי שכיר יהיה עמו הרצון בו כימי שכיר שיודע סך שכירתו לשנה או לחדש ואינו נמכר עולמי':
@51 **אם עוד רבות בשנים לפיהן ישיב גאולתו מכסף מקנתו.** ר"ל שאם היו שנים רבות עד היובל לפי מה שיעלה שנה בשנה ישיב גאולתו לפי הערך שקנהו אדוניו והמשל שאם קנהו שבעים דנרין עד היובל והיו שם ז' שנים הנה ישיב לכל שנה עשר דנרי':
@52 **אם מעט נשאר בשנים.** זה הפסוק הוא מבואר כמו שביארנו בפסוק הקודם לו אמנם יתבאר ממנו עוד דבר לא נלמדהו מהפסוק הקודם וזה שאם היה כסף מקנתו עולה לשנה יותר ממה שהוא שוה עתה בעת רצותו לגאל עצמו הנה לא ישיב גאולתו אלא כפי שניו שהם עתה שנאמר וחשב לו כפי שניו ולא אמר וחשב לו כפי השנים:
@53 **כשכיר שנה בשנה יהיה עמו.** שאין רבו מושל בו באופן הממשלה שיש לאדון על העבד שנמכר לו עולמית וזה מבואר בנפשו:
@53 **לא ירדנו בפרך לעיניך.** הזהירתנו התורה שלא נניח הגוי לרדות בעבד עברי בפרך והוא העבדות שהכונה בו לענות גוף העבד כגון שצוהו לעשות מלאכה שאינו צריך לה כדי שלא ינוח או שצוה לעשות המלאכה שהוא צרך ולא נתן לה קצבה כדי שלא ינוח:
@54 **ואם לא יגאל באלה.** ר"ל שלא יגאלוהו קרוביו ולא השיגה ידו להגאל:
@54 **ויצא בשנת היובל הוא ובניו עמו.** ר"ל בזולת כסף ואמר שיצאו בניו עמו להורות שהגוי שנמכר לו חוייב במזונות אשתו ובניו:
@55 **כי לי בני ישראל עבדים.** כבר התבאר ענינו בפרשה הקודמת:
@56 **לא תעשו לכם אלילים.** הזהירה בזה המקם מע"ז להעיר שהכונה ביובל ובשמטה להעיר ולהישיר לעבודת השם יתעלה:
@56 **ופסל מסכה לא תקימו לכם.** אחשוב כי פסל הוא צורה נעשית לנוי לא לעבודה זרה. ומצבה הוא בנין שנהגו עובדי ע"ז לבנותו בבתי ע"ז והזהירתנו התורה מעשות זה אפילו להשם יתעלה כדי שלא נסתבך באלו הפעולות המגונות היו נשקעים בהם עובדי ע"ז באותם הזמנים:
@56 **ואבן משכית לא תתנו בארצכם להשתחות עליה.** לפי שהתנה ואמר בארצכ' למדנו שלא הוזהרנו על זה חוץ לארץ ישראל וענין איסור אבן משכית היה שכבר היה מנהג עובדי ע"ז להניח אבן לפני ע"ז ושם משתחוים ליראתם והנה ענין ההשתחואה הוא לפי הוראת הגדר היא פשוט ידים ורגלים:
@57 **את שבתותי תשמורו ומקדשי תיראו.** זכר בזה המקום שמירת השבתות ויראת המקדש להעיר כי זה כלי מביא להישירנו על עבודת השם יתע' ולהרחיק מעבוד זולתו כמו העניין בשבתות ובמקדש לפי מה שביארנו במה שקדם ובכאן נשלם ביאור זאת הפרשה:

@1 והנה צותה התורה למנות שמטה לכונה בעצמה שנצטוינו לשבות ביום השביעי אלא שלא נאסרה השמטה בעשיית כל מלאכה כמו העניין ביום השבת לפי שלא יתכן שישבות האדם מכל מלאכה שנה אחת וכבר היה זה כן לפי שאין השמטה מורה על השם יתעלה כמו שיורה עליו יום השבת לפי מה שבארנו בפרשת בראשית. ואמנם הוראת השמטה על מציאות שכל נבדל עלול מהשם יתעלה ובכלל הנה העניין בשמטות וביובל כמו העניין בספירת שבעת שבועות ממחרת הפסח לקדש החמשים לפי מה שבארנו במה שקדם והנה נתקדשה השנה השביעית להעיר על מניעת הגלגל שבו כוכב מהכוכבים הרצים שהוא נכבד מאד ממניעי שאר גלגליו שירתוהו ברבוי התנועות לכוכב ההוא כמו שבארנו בספר מ"י. ולזה נתקדשו שבעה שמטות להעיר על עלוי אלו המניעים על מניעי שאר הגלגלים אשר יעבדום ולהעיר על היותם בני חורין באופן מה ביחס על אותם אשר ישרתום היה חירות מה לארץ בשנת השמטה בעניין התבואה והמלוה ונתקדשה שנת החמשים להעיר על שבכאן עלה עליונה על כל אלו המניעים הנבדלים שהם מ"ט כמו שבארנו בספר מ"י והוא השם יתעלה ולפי שהוא העשירי כשנמנה אלו הנבדלים באופן אחר כמו שזכרנו במה שקדם נתקדש יום העשירי משנת היובל והיו תוקעים בו בשופר להעיר קצת נרדמים שיתכונו במה שהעירה התורה בזה ולהורות על שררת אלו המניעים על השאר ושהן מושגחים בעניין מה שיושפע מכללות התנועות על שאר הגלגלים והמניעים כלים להם צותה התורה שתהיה השררה אשר בקרקעות כוללת ומשותפת לכל האנשים בזאת השנה כמו שזכרנו עם שבזה תועלת להטיב הדלים האמללים מתבואות השנה הזאת ולזאת הסבה בעינה צוה להשמיט המלוה בשנת השמטה כדי שתסור השררה המיוחדת על איש בזאת השנה להורות על טובות אלו המגיעים במה שישפיעו שהיא כוללת ומשותפת ואולם בשנת החמשים היה זה העניין באופן יותר שלם לפי ששררת זאת העלה היא הכוללת באמת ומאתה יושפעו השאר כמו שבארנו בשני ובחמישי מספר מלחמות השם ולזה תסר בזאת השנה כל שררה מחודשת וישוב איש לאחוזתו למשפחתו להעיר שאי לזולתו שררה על דרך האמת ומפני זה בארה התורה איך יהיה הדין בקניין הקרקעות עם שמירת זה השרש ר"ל שתשוב האחוזה לבעליה ביובל ונתן חירות עוד לבעל הקרקע לגאל הקרקע קודם בא היובל והקדים לזכור דין מכירת קרקעות קודם זכרו דין מכירתו עצמו לפי שראוי לאדם כשיצר לו שימכור קרקעותיו קודם שימכור עצמו ולזאת הסבה גם כן הקדים המכרו לישראל לדין המכרו לגר צדק או לגר תושב או לגוי עובד ע"ז כי כשיבואהו ההכרח שימכור עצמו ראוי שיבחר שימכר לישראל ולא לגר צדק כי מפני שבע מבעלי הדעות הפחותות והמדות המגונות אולי הוא נשקע בהם ויצא לתרבות רעה זה האיש בהמכרו לו כי ילמד ממעשיו וכ"ש שראוי שירחיק יותר המכר לגר תושב שאין מאמין בתורת משה וכ"ש שראוי שירחיק יותר ההמכר לגוי עובד ע"ז והנה מה שהחמירה התורה בעניין מכירת בית מושב עיר חומה שלא תהיה לו גאולה כי אם עד שנה אחד ולא יצא ביובל הוא מבואר התועלת והוא לפי מה שאחשוב כדי להעמיד ישוב זה המקום הנכבד המוקף וזה שאם היה יוצא ביובל לא יהיה הקונה משגיח בעניין תקון הבית ההוא ויתקלקל ויפול ויהיה זה סבה אל חורבן המקום ההו' והנה בעניין שוב האחוזה לבעליה ביובל ושוב האדם למשפחתו תועלת אחר וזה כי יהיה סבה שלא יהיו נואשים מטוב האנשים הקשי יום דעתם כי בבא היובל ישובו אל קנייניהם ולזה יהיה בהם חריצות להשתדל לאסוף ולכנוס מה שייצטרך למחיתם ולא יתרשלו ותרפינה ידיהם לחשבם שאין להם תקומה עוד כמו שתראה בקצת האנשים שהם נואשים מטוב לזאת הסבה והיה זה הסבה אל התמדת חסרונם ולפי שזה העניין היה להשגחה על הדלים סמך לזה האזהרה מליקח מאתם נשך ותרבית עם שכבר זכר זה גם כן לפי שכבר יזכור במה שיבא שבשנ' השמטה תשמט המלוה והנה זכר דין עבד כנעני שאינו יוצא ביובל עם זכירתו יציאת עבד עברי ביובל להשלמת הביאור בזה הענין. עם שבזה למדתנו התורה כי זה החירות נתן לישראל מפני היותם נמשכים לעבודתו ית' כי זה ממה שיישירם לעבודתו כמו שהתבאר מדברינו ולזה לא נתן זה החירות לזולתם מן האומות בהמכרם והמשיך לזה האזהרה מעבוד ע"ז להעיר שזאת המצוה היא מישירה אל ההרחקה מתת האלהות לזולת השם יתעלה והמשל כי מי שיחשוב שהשם יתעלה שהוא המניע אשר לגלגל הכוכבים הקיימים כמו שחשבו הרבה מהפילוסופים כבר נתן האלהו' למי שאינו אלוה ולזה הישירתנו התורה בזה הדעת האמתי משני פנים האלה ר"ל בקדוש החמשים ובקדוש העשירי וזה כי כשנמנו כל השכלים הנפרדים בכללם היו חמשים עם השם יתעלה שהוא התחלתם וכאשר לא נמנו המשרתים למניעי גלגל הכוכבים היו עשרה עם השם יתעלה שהוא העשירי שיושפעו ממנו השאר כמו שביארנו בספר מלחמות הש' והמשיך לזה ג"כ הצואה בשמירת השבתו' ובשמירת המקדש כי הם גם כן מישירי' על זה העניין בעינו כמו שתתבאר מדברינו במה שקדם ואמנם התועלות המגיעות מזאת הפרשה הם שמנה:
@1 **התועלת** הראשון הוא במצות והוא מה שנצטוינו על שביתת הארץ והאילנות בשנת השמטה והוזהרנו מהזריעה והקצירה והזמירה והבצירה וכבר נתבאר מדברינו התועלת מזאת המצוה:
@1 **התועלת** הב' הוא במצות והוא מה שנצטוינו לקדש שנת היובל אחר עבור מ"ט שנה ולקרא דרור בארץ לכל יושביה באופן שישוב איש אל אחוזתו ואיש אל משפחתו ולבות הארץ מהעבודה כמו העניין בשנת השמטה ולתקוע בשופר עשור לחדש השביעי בשנת היובל וכבר נתבאר מדברינו התועלות המגיעות מאלו המצות:
@1 **התועלת** הג' הוא במצות והוא מה שהוזהרנו מלהונות בענין מקח וממכר אפיל בדברים והנה התועלת בזאת המצוה מבואר בתקון הקבוץ המדינה:
@1 **התועלת** הד' הוא במצות והוא מה שזכרה התורה מדיני מוכר מאחוזתו ומוכר בית בערי חומר וכבר נתבאר מדברינו התועלת המגיע מזאת האזהרה במה שקדם:
@1 **התועלת** הה' הוא במצות והוא מה שהזהירה התורה מלשנות בערי הלויים דבר ממה שהוא עליו ר"ל שלא נשיב שדה מגרש או הפך ושלא להשיב השדה או המגרש עיר או הפך וכבר ביארנו התועלת המגיע מזאת האזהרה במה שקדם:
@1 **התועלת** הו' הוא במצות והוא מה שהזהירה התורה מליקח איש מאחיו נשך ותרבית כי בזה מההפסד בקבוץ המדיני מה שלא יעלם עם שבזה הענין יקנה לאדם תכונות מגונות לרוב השתדלותו באסיפת הממון עם שכבר יתחכם תמיד להמציא מעות למי שיראה שיוכל להרויח עמו מצד חסרון דעתו ורבוי קנייניו וישתדל בתחבולות רבות שיקח מעות ממנו להשיג מבוקשיו:
@1 **התועלת** הז' הוא במצות והוא מה שבארה התור' מדיני הנמכר לעבד מישראל לישראל או לגר צדק או לגוי ודיני הנמכר לישראל משאר האומות וכבר נתבאר מדברינו התועלת המגיע מאלו המצות:
@1 **התועלת** הח' הוא במצות והוא מה שהזהירה התורה מהקים מצבה ומהשתחוות על אבן משכית אפילו לש"י מאלו וכבר נתבאר מדברינו התועלת המגיע האזהרות ואולם שרשי המצות הנזכרות בזאת הפרשה הנה ממצוה הראשונה הוא מה שצונו לשבות הארץ ממלאכה בשנת השמטה:
